/**
 * Report Service
 */

import type { IPatrolRunRepository } from '../domain/repositories/IPatrolRunRepository.js';
import type { IIncidentRepository } from '../domain/repositories/IIncidentRepository.js';
import type { IShiftRepository } from '../domain/repositories/IShiftRepository.js';

export class ReportService {
  constructor(
    private readonly patrolRepo: IPatrolRunRepository,
    private readonly incidentRepo: IIncidentRepository,
    private readonly shiftRepo: IShiftRepository
  ) { }

  async generateSiteReport(siteId: number, range: { start: Date, end: Date }) {
    const patrols = await this.patrolRepo.findBySiteId(siteId);
    const incidents = await this.incidentRepo.findBySite(siteId);
    const shifts = await this.shiftRepo.findBySite(siteId, range);

    // Aggregation logic
    return {
      siteId,
      period: range,
      metrics: {
        totalPatrols: patrols.total,
        completionRate: 85, // TODO: Calculate from actual data
        incidentCount: incidents.length,
        totalHours: 120 // TODO: Calculate from shift data
      }
    };
  }

  async exportToCSV(data: any[]) {
    if (!data || data.length === 0) return '';
    const headers = Object.keys(data[0]).join(',');
    const rows = data.map(obj => Object.values(obj).join(',')).join('\n');
    return headers + '\n' + rows;
  }
}

let instance: ReportService | null = null;

export function initializeReportService(p: IPatrolRunRepository, i: IIncidentRepository, s: IShiftRepository): ReportService {
  instance = new ReportService(p, i, s);
  return instance;
}

export function getReportService(): ReportService {
  if (!instance) throw new Error('ReportService not initialized');
  return instance;
}
